// SafeNexus HSE — Fire & Life Safety, FLS-11 to FLS-20
// Separate content module. Existing FLS-01–10 source is intentionally untouched.
// Confirm current authority-approved UAE/local requirements and project specifications
// before applying numeric design, testing, or maintenance criteria. International
// standards are supplementary unless adopted by the authority or contract.

import 'package:flutter/material.dart';
import 'fire_science_prevention.dart';

class FireSciencePreventionTopics11To20 {
  static const List<FireSafetyTopic> topics = [
    FireSafetyTopic(
      id: 'FLS-11', title: 'Fire Pumps & Fire Water Supply Systems',
      subtitle: 'Reliable water supply, pump-room safety and impairment control',
      icon: Icons.water_damage_rounded, accent: Color(0xFF1976D2),
      overview: 'Fire pumps support the approved fire-water network when the available supply cannot provide the required pressure and flow. System design, duty points, redundancy, acceptance testing and maintenance must follow approved drawings, authority requirements and the adopted standard. Never change valves, controllers or set points without authorization.',
      sections: [
        FireSafetySection('System purpose & components', ['Typical arrangement may include a water source/tank, suction and discharge pipework, duty pump, standby pump, jockey pump, controllers, test header/flow meter, isolation valves, pressure gauges and alarms.', 'The jockey pump maintains normal pressure within its designed band; it is not a substitute for the main fire pump.', 'Electric and diesel drivers have different readiness needs. Diesel systems require suitable fuel, batteries, cooling, exhaust and ventilation.', 'Use approved hydraulic calculations, pump curves, cause-and-effect and as-built drawings; do not infer capacity from motor size alone.']),
        FireSafetySection('Hazards & consequences', ['Loss of supply from closed or failed valves, depleted tank, blocked suction, air ingress or inadequate replenishment.', 'Unexpected automatic start, rotating machinery, hot surfaces, noise, exhaust fumes and electrical energy.', 'Water discharge can cause flooding, slips, equipment damage and electrical hazards.', 'Uncontrolled modification can reduce pressure/flow to remote or elevated points.']),
        FireSafetySection('Controls & operation', ['Keep pump room access, ventilation, drainage, lighting and identification suitable and unobstructed.', 'Maintain valve position supervision and seals/locks as specified; verify status against the approved valve schedule.', 'Protect controllers and power supplies; provide authorized access and prevent casual reset or isolation.', 'Use approved test arrangements and competent personnel. Manage discharge safely and avoid water hammer.', 'For diesel units, inspect fuel quality/quantity, battery condition, coolant, lubrication, exhaust and leak condition per manufacturer instructions.']),
        FireSafetySection('Inspection, testing & impairment', ['Routine checks, churn/no-flow checks, flow tests and annual/periodic performance tests must follow the applicable approved maintenance schedule and adopted code; do not invent a universal interval.', 'Record suction/discharge pressures, speed, flow, driver readings, alarms, start/stop behaviour, defects and corrective actions.', 'Before planned impairment, obtain authorization, risk assess, notify affected parties and authority where required, establish compensating measures and define restoration verification.', 'After maintenance, return valves to approved normal position, remove bypasses/isolations, test interfaces and formally close impairment.']),
        FireSafetySection('Emergency / stop-work', ['Report abnormal vibration, overheating, leaks, repeated starts, low tank level, controller fault or unavailable pump immediately.', 'Do not enter unsafe flooded or electrically compromised rooms; isolate only under authorized procedure.', 'If protection is impaired, activate the site impairment plan, fire watch or other approved temporary controls and escalate to the responsible fire-safety authority.']),
        FireSafetySection('Commissioning, readiness & troubleshooting', [
          'Confirm the installed pump set matches approved duty/standby philosophy, design flow and pressure, power supply, tank arrangement and cause-and-effect matrix; compare actual results only with approved acceptance criteria.',
          'During a witnessed test, use calibrated instruments and the approved test return/discharge route. Keep personnel clear of couplings, rotating shafts, hot exhausts and pressurized connections.',
          'Investigate frequent jockey-pump cycling, pressure decay, unusual noise, seal leakage, abnormal temperature or unexpected controller alarms; record trends and refer repairs to an authorized fire-system specialist.',
          'Before handover, verify labels, valve normal positions, controller mode, alarm transmission, remote monitoring, access keys and operator training.',
        ]),
       ],
       checklist: ['Approved pump and water-supply drawings available','Room access, ventilation, drainage and housekeeping acceptable','Valve status matches approved schedule','Controller normal; alarms and power/driver readiness checked','Tank level and water supply status verified','Test and maintenance records reviewed','Impairments authorized, communicated and tracked to restoration'],
      requiredDocuments: ['Approved fire strategy and hydraulic calculations','Pump data sheets, curves and commissioning/acceptance records','As-built drawings and valve schedule','Inspection, testing and preventive-maintenance logs','Impairment permit, notifications and restoration certificate','Competency and contractor records'],
      interviewQuestions: [FireSafetyQuestion('What is the role of a jockey pump?', 'It maintains system pressure within its designed operating band and limits unnecessary main-pump starts; it cannot replace the fire pump.'), FireSafetyQuestion('What do you do if a fire pump is unavailable?', 'Raise an impairment, notify responsible management and required stakeholders, assess risk, implement approved compensating measures, and verify restoration before closing it.'), FireSafetyQuestion('Can a valve be closed to stop a leak?', 'Only through the authorized impairment/isolation procedure with impact assessment, notifications and compensating protection.')],
      references: ['Applicable UAE Fire and Life Safety Code and current authority approvals','Approved project fire strategy, hydraulic calculations and O&M manuals','NFPA 20 / NFPA 25 only where adopted by authority or contract','Manufacturer instructions and approved maintenance schedule'],
    ),
    FireSafetyTopic(
      id: 'FLS-12', title: 'Fire Hydrants, Hose Reels & Fire Hoses',
      subtitle: 'First-aid firefighting water outlets, access and safe use',
      icon: Icons.water_drop_rounded, accent: Color(0xFF1565C0),
      overview: 'Hydrants, hose reels and fire hoses provide water for trained responders or occupants where the approved fire strategy permits. Their location, pressure, flow, hose type and use must match the installed system and local authority approval. Occupants should prioritize alarm and evacuation; firefighting is only for trained persons, a small incipient fire and a safe escape route.',
      sections: [
        FireSafetySection('Equipment & application', ['Hydrants may be external or internal and connect to the approved fire main; hose reels are intended for the specific class of fire and user capability stated by the site plan.', 'Hoses, couplings, branch/nozzles, cabinets, landing valves and signage must be compatible and approved.', 'Identify outlet type, operating instructions, pressure limitations and access restrictions before use.', 'Do not use water on energized electrical equipment, flammable-liquid fires or reactive materials unless the approved agent and procedure specifically permit it.']),
        FireSafetySection('Hazards & consequences', ['Blocked or inaccessible hydrants delay response and can obstruct emergency vehicles.', 'Hose reaction, high pressure, coupling failure, hose whip, slips and uncontrolled water discharge can injure users.', 'Incorrect agent selection can spread burning liquid, cause electric shock or intensify a reaction.', 'Damaged, kinked, aged or incorrectly coupled hose can fail under pressure.']),
        FireSafetySection('Access & controls', ['Keep hydrants, cabinets, landing valves and fire-service access clear, visible and protected from vehicle impact.', 'Maintain identification, caps, seals, hose condition, nozzle, cabinet, drainage and corrosion protection.', 'Use trained staff, team communication and a clear retreat route; never fight a fire that is growing, producing dense smoke or blocking escape.', 'After use, report immediately, isolate/refill only under authorized procedure, dry/inspect/repack as required and restore readiness.']),
        FireSafetySection('Inspection & records', ['Inspect at the frequency set by authority-approved maintenance plan and manufacturer; distinguish visual checks from flow/performance testing.', 'Check physical damage, leakage, access, signage, cabinet contents, hose condition and valve operation by competent personnel.', 'Record asset ID/location, findings, test method/results, defects, isolation and return-to-service confirmation.', 'Do not assume a hose reel or hydrant is operational merely because its cabinet is present.']),
        FireSafetySection('Emergency use', ['Raise alarm and call emergency response first where safe; select the correct equipment only if trained and conditions remain tenable.', 'Keep an exit behind you; stop immediately if smoke, heat, fire size or uncertainty increases.', 'Never direct water toward live electrical equipment or unknown chemical involvement.']),
        FireSafetySection('Deployment method & user competency', [
          'Before deployment, identify the outlet and hose type, confirm that the water source is available, and ensure a trained team can manage nozzle reaction and communication.',
          'Lay hose without sharp bends, vehicle crossings or trip hazards where practicable; protect it from doors, edges, hot surfaces and moving equipment.',
          'Open valves in the sequence stated by the equipment instructions; control the nozzle and never disconnect a pressurized hose or coupling.',
          'After use, report the asset out of service until it has been inspected, drained/dried as specified, repacked correctly and formally returned to normal readiness.',
        ]),
       ],
       checklist: ['Outlet clearly identified and accessible','No vehicle obstruction or stored materials','Cabinet, hose, nozzle, coupling and seals intact','No visible leak, corrosion or damage','Inspection/test status current per approved plan','Users know alarm-first and safe-retreat rule'],
      requiredDocuments: ['Approved fire-fighting layout and asset register','Hydrant/hose reel inspection and test records','Defect and corrective-action log','Training records and emergency plan','Impairment/isolation and restoration records'],
      interviewQuestions: [FireSafetyQuestion('When should an occupant use a hose reel?', 'Only when trained, the fire is incipient, the correct equipment is available, alarm/response has been raised and a safe escape route remains.'), FireSafetyQuestion('Why must hydrants remain unobstructed?', 'Responders need rapid access and sufficient operating space; obstruction delays deployment and can compromise emergency access.'), FireSafetyQuestion('What is required after hose use?', 'Report it, have it inspected and restored by authorized personnel, and confirm the system is ready before closing the issue.')],
      references: ['Current UAE Fire and Life Safety Code and authority-approved fire strategy','Approved site fire plan, equipment labels and manufacturer instructions','NFPA 14 / NFPA 25 where adopted by authority or contract'],
    ),
    FireSafetyTopic(
      id: 'FLS-13', title: 'Automatic Fire Sprinkler Systems',
      subtitle: 'Water-based automatic suppression, obstruction control and impairment',
      icon: Icons.grain_rounded, accent: Color(0xFF00897B),
      overview: 'Automatic sprinklers are designed to operate in response to heat at individual sprinkler heads and control or suppress fire within the system design basis. They are not smoke detectors. Head type, spacing, temperature rating, hazard classification, water supply and maintenance are governed by approved design and applicable authority requirements.',
      sections: [
        FireSafetySection('System fundamentals', ['Typical systems include control valves, alarm/check valves, piping, sprinkler heads, water supply, flow/pressure switches and monitoring interfaces.', 'Most conventional sprinkler heads operate individually when their thermal element reaches its rated condition; not every head discharges simultaneously.', 'Different systems (wet, dry, pre-action, deluge) have distinct operating logic and environmental applications.', 'Never paint, hang objects from, relocate, cover or replace sprinkler heads with an unapproved type.']),
        FireSafetySection('Hazards & failure modes', ['Obstructed discharge pattern from storage, partitions, temporary works or decorative items.', 'Closed valve, low supply, damaged pipe, frozen/overheated component or unauthorized isolation.', 'Accidental discharge, water damage, slips and electrical exposure.', 'Wrong head type or changed storage arrangement can invalidate the approved design assumptions.']),
        FireSafetySection('Prevention & field controls', ['Maintain approved clearance below sprinklers and required access to valves; use the actual approved design/code rather than a generic distance.', 'Control changes to storage height, commodity, rack layout, ceiling, partitions and occupancy through management of change and fire-system review.', 'Protect heads from impact; report missing escutcheons, corrosion, leakage, paint, loading or damage.', 'Ensure control valves are secured/supervised in the approved normal position and monitoring signals are functional.']),
        FireSafetySection('Inspection & impairment', ['Competent personnel perform visual inspections, alarm tests, waterflow tests and maintenance to the authority-approved schedule and adopted standard.', 'Record valve status, gauge condition, leaks, obstruction, head condition, alarm interface and corrective actions.', 'Treat any closed valve, failed alarm, depleted supply or damaged piping as an impairment; authorize, notify, compensate and restore formally.', 'After work, verify valves, drains, supervisory signals, alarm transmission and return-to-service status.']),
        FireSafetySection('Response', ['On sprinkler activation, raise alarm, evacuate and call emergency services; do not shut off water to protect property unless authorized incident command directs it.', 'Keep clear of discharge and electrical hazards; responders coordinate isolation after fire control.', 'Report accidental damage immediately and protect the area from further impact.']),
        FireSafetySection('Design interfaces & impairment safeguards', [
          'Verify sprinkler hazard classification, coverage, head type/orientation, spacing, obstruction rules and hydraulic design against approved drawings—not generic field assumptions.',
          'Do not paint, hang items from, shield, relocate or replace sprinkler heads without approved design review and competent authorization.',
          'Coordinate ceiling works, storage-height changes, hot work, dust-producing activity and temporary heating with the fire-system owner; protect heads from impact and contamination.',
          'For a valve closure, drained zone, damaged head or failed water supply, use formal impairment control, affected-area notification, approved temporary measures and documented restoration/testing.',
        ]),
       ],
       checklist: ['Sprinkler heads unobstructed, unpainted and undamaged','Storage/layout remains within approved design assumptions','Control valves secured and normal','No leakage, corrosion or unauthorized alteration','Alarm/supervisory tests current','Impairment and restoration records complete'],
      requiredDocuments: ['Approved sprinkler design and hydraulic calculations','System drawings, valve schedule and asset register','Inspection, testing and maintenance records','Management-of-change approvals for layout/storage','Impairment permits, notifications and restoration records'],
      interviewQuestions: [FireSafetyQuestion('Do all sprinkler heads activate together?', 'Typically no. Individual heads operate when their thermal element reaches its operating condition, subject to system type.'), FireSafetyQuestion('What if storage is raised close to sprinkler heads?', 'Stop the change and obtain competent fire-protection review against approved design and applicable requirements before storing.'), FireSafetyQuestion('Who may isolate a sprinkler system?', 'Only authorized competent personnel under the formal impairment process, with notifications, compensating measures and verified restoration.')],
      references: ['Current UAE Fire and Life Safety Code and authority-approved design','Approved drawings, cause-and-effect and O&M manual','NFPA 13 / NFPA 25 where adopted by authority or contract'],
    ),
    FireSafetyTopic(
      id: 'FLS-14', title: 'Fire Suppression Systems – Clean Agent, CO₂ & Foam',
      subtitle: 'Special hazard systems, exposure prevention and discharge response',
      icon: Icons.cloud_rounded, accent: Color(0xFF6A1B9A),
      overview: 'Special hazard suppression systems protect defined enclosures or process risks using an agent selected for the hazard and occupancy. Clean agents, carbon dioxide and foam have different mechanisms and life-safety implications. System design, concentration, enclosure integrity, alarms, time delays and re-entry rules must come from approved engineering and authority requirements.',
      sections: [
        FireSafetySection('Agent selection & system elements', ['Clean-agent systems may use gaseous agents; CO₂ systems can create immediately dangerous oxygen-deficient atmospheres; foam is used for specified flammable-liquid hazards.', 'Components may include cylinders, manifolds, piping, nozzles, detection, release panel, abort/manual controls, warning devices and pressure relief.', 'Confirm the protected hazard, enclosure, agent, design concentration and occupancy restrictions from approved documents.', 'Never obstruct nozzles, alter cylinders, disable release circuits or substitute agents without engineering approval.']),
        FireSafetySection('Hazards & consequences', ['CO₂ discharge can cause fatal asphyxiation; clean-agent exposure and decomposition products may present hazards depending on agent, concentration and fire conditions.', 'Unexpected release, noise, pressure, cold discharge, visibility loss and panic can injure occupants.', 'Foam concentrate may create slip, environmental or compatibility concerns; runoff may require containment.', 'Enclosure leakage, open doors or changed volume can prevent required concentration or performance.']),
        FireSafetySection('Engineering & administrative controls', ['Provide approved detection, pre-discharge alarm, time delay, manual release/abort arrangements and signage as designed.', 'Maintain controlled access, cylinder restraint, identification, pressure/weight status and protected piping/nozzles.', 'Before maintenance, apply lockout/isolation and formal impairment controls; prevent inadvertent discharge.', 'Conduct evacuation drills and train staff on alarm meanings, immediate exit and prohibition on re-entry until authorized.', 'For foam, confirm product SDS, containment, disposal and environmental requirements.']),
        FireSafetySection('Inspection & maintenance', ['Use competent specialist technicians and manufacturer/authority-approved intervals and procedures.', 'Verify cylinder condition/charge, valves, pipe/nozzle integrity, detection, alarms, release circuits, room integrity and interfaces as applicable.', 'Any disabled system requires impairment authorization, notifications, compensating measures and documented restoration.', 'Do not conduct live discharge tests unless specifically planned, approved, risk assessed and controlled.']),
        FireSafetySection('Discharge response', ['Evacuate the protected space immediately on pre-discharge alarm or release; do not delay to investigate.', 'Raise alarm, account for people and prevent re-entry. Call emergency services and inform responders of agent type and possible exposure.', 'Re-entry only after competent incident command confirms atmosphere and conditions safe; rescue in oxygen-deficient atmosphere requires trained, equipped responders.']),
        FireSafetySection('Release logic, evacuation & post-discharge', [
          'Confirm the protected hazard, agent suitability, enclosure integrity, detection/release sequence, abort/manual controls and warning devices from approved cause-and-effect documents.',
          'Before testing or maintenance, isolate/release-disable only under an authorized permit, notify occupants and control room, and apply compensating fire protection.',
          'For total-flooding systems, evacuate on pre-discharge warning; never remain in a protected enclosure during a release. CO₂ discharge presents potentially fatal oxygen-displacement risk.',
          'After discharge, prevent re-entry until the competent response team confirms safe atmosphere and conditions; replenish agent and restore detection/release functions through authorized service personnel.',
        ]),
       ],
       checklist: ['Agent and protected hazard identified','Cylinder/manifold and piping visually sound','Nozzle discharge path unobstructed','Detection, warning and release controls status verified by competent person','Room signage and evacuation instructions visible','Impairment controls and re-entry procedure known'],
      requiredDocuments: ['Approved suppression design and cause-and-effect','Agent SDS and equipment manuals','Cylinder inspection/weight/pressure and maintenance records','Enclosure integrity/test records where applicable','Impairment and restoration certificates','Training, drill and emergency response records'],
      interviewQuestions: [FireSafetyQuestion('Why is CO₂ discharge especially hazardous?', 'It can displace oxygen and cause rapid loss of consciousness or death; evacuate and prohibit entry until competent responders confirm safe conditions.'), FireSafetyQuestion('Can staff re-enter after an agent discharge?', 'No, not until the incident commander/competent authority confirms the atmosphere and space are safe.'), FireSafetyQuestion('What must happen before servicing a suppression panel?', 'Authorized isolation, impairment notification and compensating measures, protection against inadvertent release, competent work and documented restoration.')],
      references: ['Current UAE Fire and Life Safety Code and authority-approved system design','Agent SDS, manufacturer manuals and approved emergency plan','NFPA 12 / 2001 / 11 / 25 only where adopted by authority or contract'],
    ),
    FireSafetyTopic(
      id: 'FLS-15', title: 'Smoke Control, Ventilation & Smoke Extraction',
      subtitle: 'Smoke movement, pressurization, extraction and fire-mode interfaces',
      icon: Icons.air_rounded, accent: Color(0xFF546E7A),
      overview: 'Smoke-control systems manage smoke movement to support evacuation and firefighting according to the approved fire strategy. They may use extract fans, make-up air, stair/lobby pressurization, dampers and automatic controls. Normal HVAC operation is not equivalent to a smoke-control mode; only approved cause-and-effect and fire-service procedures govern operation.',
      sections: [
        FireSafetySection('System purpose & components', ['Systems may include smoke extract fans, shafts, fire/smoke dampers, make-up air, stair pressurization, control panels, sensors and fire alarm interfaces.', 'Fire mode can differ from comfort ventilation and may require selected fans to stop, start or change state.', 'Door opening, building leakage, wind, stack effect and changed partitions affect performance.', 'Use approved fire strategy, cause-and-effect matrix and commissioning results to understand the intended sequence.']),
        FireSafetySection('Hazards & consequences', ['Failure or incorrect fan/damper sequence can spread smoke into escape routes or prevent intended smoke clearance.', 'Unplanned opening of doors or windows can alter pressure and smoke flow.', 'Fan, belt, electrical and access hazards during maintenance; hot smoke and toxic gases during incidents.', 'Blocked grilles, storage in shafts or unauthorized fit-out can compromise performance.']),
        FireSafetySection('Controls & maintenance', ['Keep smoke outlets, inlets, shafts, dampers and access panels unobstructed and correctly identified.', 'Control building modifications through fire-engineering review and management of change.', 'Test interfaces, feedback signals, power supplies, fan rotation, damper movement and sequences under approved test plans.', 'Do not manually override fire mode unless authorized by incident command or approved procedure.', 'Maintenance requires safe isolation, access controls and reinstatement checks.']),
        FireSafetySection('Inspection & records', ['Use competent specialists and approved test intervals; record each device/zone, commanded state, actual feedback, defect and closure.', 'Verify cause-and-effect against approved matrix after alarm, BMS or fit-out changes.', 'Treat failed smoke control as a fire-protection impairment with risk assessment, notifications and temporary measures.', 'Confirm all overrides and test modes are removed and normal/standby readiness restored.']),
        FireSafetySection('Emergency response', ['Follow building evacuation and incident-command instructions; do not enter smoke to operate a panel.', 'Fire service or designated authorized personnel control smoke-system overrides.', 'Report unexpected smoke migration, fan noise/failure, blocked louvres or control faults immediately.']),
        FireSafetySection('Smoke-control operation & functional verification', [
          'Identify the approved fire mode for each zone, including fan start/stop, damper position, door interfaces, lift/lobby effects and fire-alarm control sequence.',
          'Keep smoke shafts, grilles, dampers, fan rooms and control panels unobstructed; do not wedge fire doors or alter ventilation settings to improve comfort.',
          'Testing must confirm actual airflow/pressure or other specified performance using the approved method and acceptance values; a fan running indication alone does not prove smoke-control performance.',
          'If a fan, damper, sensor or control interface fails, notify building control, assess affected zones and apply the approved impairment/evacuation arrangements.',
        ]),
       ],
       checklist: ['Smoke outlets, inlets and access clear','No unauthorized HVAC/partition/door changes','Control panel normal and faults escalated','Testing and cause-and-effect records current','Overrides/test modes removed after work','Impairment response and contacts available'],
      requiredDocuments: ['Approved fire strategy and smoke-control calculations','Cause-and-effect matrix and as-built drawings','Commissioning and periodic test reports','Maintenance and defect closure logs','Impairment permits and restoration evidence'],
      interviewQuestions: [FireSafetyQuestion('Is comfort HVAC the same as smoke control?', 'No. Smoke control is an engineered fire mode with specific sequences, interfaces and performance objectives.'), FireSafetyQuestion('What if a smoke-extract fan fails?', 'Raise a fire-system impairment, notify responsible parties, assess risk, implement approved temporary measures and arrange competent repair/testing.'), FireSafetyQuestion('Can a worker override a smoke-control panel?', 'Only if specifically authorized under the approved procedure or incident command.')],
      references: ['Current UAE Fire and Life Safety Code and approved fire strategy','Approved smoke-control calculations, cause-and-effect and commissioning documents','Applicable adopted engineering standards and manufacturer instructions'],
    ),
    FireSafetyTopic(
      id: 'FLS-16', title: 'Fire Alarm Panels, Detectors & Manual Call Points',
      subtitle: 'Detection, alarm transmission, zoning and fault management',
      icon: Icons.notifications_active_rounded, accent: Color(0xFFC62828),
      overview: 'Fire alarm systems detect defined fire signatures, alert occupants and transmit signals to approved interfaces. Devices include smoke/heat/flame detectors, manual call points, sounders, visual alarms, control/indicating equipment and monitoring links. Alarm response and evacuation must follow the approved cause-and-effect, site emergency plan and authority requirements.',
      sections: [
        FireSafetySection('Devices & functions', ['Smoke, heat, flame and other detectors have different applications and limitations; selection follows hazard and approved design.', 'Manual call points allow people to initiate an alarm; sounders and visual devices alert occupants.', 'Panels indicate zones/addresses, alarms, faults, disablements and supervisory conditions; monitoring may connect to remote responders.', 'Detector location, spacing, type and sensitivity are design matters; do not relocate or cover devices.']),
        FireSafetySection('Hazards & failure modes', ['Disabled, isolated, dirty, painted or obstructed detector may fail to detect promptly.', 'Faulty wiring, power/battery issues, network failure or incorrect programming can impair alarm transmission.', 'False alarms can cause complacency, but must never be ignored or silenced without investigation and authorization.', 'Unapproved changes to zones/cause-and-effect can delay evacuation or trigger unsafe interfaces.']),
        FireSafetySection('Operational controls', ['Keep panel access restricted to trained authorized persons; maintain zone charts, response instructions and contact details.', 'Do not silence, reset, isolate or disable without following the approved alarm response and authorization process.', 'For planned detector work, identify affected area, obtain impairment approval, notify occupants/control room and arrange compensating measures.', 'Manage dust, steam and hot work to reduce nuisance alarms only through approved temporary arrangements; restore devices promptly.', 'After a genuine alarm, investigate only when safe and under incident command; never assume it is false.']),
        FireSafetySection('Testing & records', ['Competent technicians test devices, manual call points, sounders, batteries, transmission and interfaces on the approved schedule.', 'Record device ID/location, method, result, panel response, remote receipt, faults and repair verification.', 'After any change, test relevant cause-and-effect and update as-built drawings, zone plans and asset register.', 'Close impairment only after all devices and signals are restored and verified.']),
        FireSafetySection('Alarm response', ['On alarm, stop work, alert others and evacuate using designated routes; do not use lifts unless specifically designated for evacuation.', 'Proceed to assembly point, report missing persons and await instructions; do not re-enter until authorized.', 'Call emergency services/site control per plan and give precise location and observed conditions.']),
        FireSafetySection('Alarm response, fault handling & change control', [
          'Know the difference between alarm, supervisory, trouble/fault and isolation signals; follow the site cause-and-effect and escalation matrix rather than silencing or resetting blindly.',
          'On alarm, initiate the approved response, identify the zone/device, dispatch trained verification only when safe, and avoid delaying evacuation while seeking confirmation.',
          'Detector relocation, loop changes, software edits, device replacement and cause-and-effect changes require authorized competent personnel, documented configuration control and functional re-test.',
          'After testing, confirm every device, sounder, interface, transmission path and isolated point is restored; communicate any remaining impairment and record panel event details.',
        ]),
       ],
       checklist: ['Panel normal; alarm/fault/disablement status reviewed','Zone chart and response instructions current','Detectors and call points visible and unobstructed','Sounders/visual alarms not blocked or disconnected','Testing, battery and transmission records current','All temporary isolations formally restored'],
      requiredDocuments: ['Approved fire alarm drawings and cause-and-effect matrix','Zone/address schedule and device register','Inspection, test and maintenance reports','Alarm, false-alarm and incident logs','Impairment/isolation permits and restoration verification','Training and evacuation drill records'],
      interviewQuestions: [FireSafetyQuestion('What is the difference between alarm, fault and disablement?', 'Alarm indicates a fire condition; fault indicates system/equipment abnormality; disablement means a function/device has intentionally been taken out of service.'), FireSafetyQuestion('Can a worker reset a fire alarm?', 'Only authorized trained personnel after following the site procedure and confirming the condition is understood and safe.'), FireSafetyQuestion('What should workers do when the alarm sounds?', 'Stop work, evacuate by safe designated route, report to assembly point and await all-clear from authorized incident management.')],
      references: ['Current UAE Fire and Life Safety Code and authority-approved fire alarm design','Approved cause-and-effect, emergency plan and O&M manuals','NFPA 72 only where adopted by authority or contract'],
    ),
    FireSafetyTopic(
      id: 'FLS-17', title: 'Fire Safety in Construction Sites',
      subtitle: 'Temporary works, combustible storage, welfare and changing site conditions',
      icon: Icons.construction_rounded, accent: Color(0xFFEF6C00),
      overview: 'Construction sites have changing fire loads, temporary power, hot work, incomplete compartmentation and evolving escape routes. The principal contractor and employers must coordinate a site-specific fire risk assessment, emergency arrangements and protection measures aligned with applicable UAE/local requirements, approved project plans and Civil Defence conditions.',
      sections: [
        FireSafetySection('Site-specific fire risk', ['Assess work phases, temporary buildings, access, occupancy, storage, flammable liquids/gases, charging areas, hot work and adjacent occupied premises.', 'Plan escape routes and assembly points as the site changes; maintain safe access for emergency vehicles.', 'Identify incomplete alarms, sprinklers, fire doors, compartmentation and temporary protection gaps.', 'Coordinate subcontractors, night shifts, visitors and language needs through induction and toolbox talks.']),
        FireSafetySection('Hazards & consequences', ['Hot work sparks ignite insulation, packaging, timber, waste or concealed voids.', 'Temporary electrical faults, overloaded circuits, damaged leads and battery charging can initiate fire.', 'LPG/fuel/solvent leaks, incompatible storage and poor ventilation can create flash-fire or explosion risk.', 'Blocked stairs, hoists, scaffold access and changing layouts can trap workers or delay response.']),
        FireSafetySection('Prevention & controls', ['Apply permit-to-work for hot work and other high-risk tasks; inspect area before, during and after work under approved site procedure.', 'Keep combustible waste controlled and remove it routinely; segregate flammables in approved, ventilated, secured areas with spill controls.', 'Use inspected temporary electrical distribution, suitable protection and competent installation; prohibit unauthorized wiring.', 'Provide suitable temporary alarm, extinguishers, signage, emergency lighting and fire points for each phase as determined by risk assessment and approved plan.', 'Maintain stairs, exits, gates, fire-service routes and assembly areas; do not rely on a single access route without approved contingency.', 'Manage cylinders upright/secured, caps fitted when not connected, separated and stored per applicable requirements and SDS.']),
        FireSafetySection('Coordination & assurance', ['Review fire risk assessment at phase changes, occupancy changes, hot-work campaigns and after incidents/near misses.', 'Conduct documented inspections with responsible persons and close actions before work continues.', 'Drill workers and subcontractors; verify headcount, alarm audibility, communication and night-shift arrangements.', 'Any impairment of permanent fire protection requires formal approval, notification and compensating measures.']),
        FireSafetySection('Emergency actions', ['Raise alarm, stop work, evacuate, account for personnel and call emergency services/site response.', 'Do not use construction lifts or enter smoke; keep gates and emergency access clear.', 'Only trained responders may attempt incipient firefighting with safe escape; report cylinders, chemicals and energy sources to responders.']),
        FireSafetySection('Construction-phase fire risk controls', [
          'Prepare a site fire plan for each phase: access for fire appliances, temporary escape routes, assembly points, alarm method, water supply, emergency contacts and responsible persons.',
          'Control combustible waste, temporary accommodation, hot work, temporary electrics, fuel/chemical storage, charging areas and work near occupied buildings through task risk assessment and permits.',
          'Maintain temporary protection and fire separation as the structure rises; do not remove or bypass existing systems without approved impairment controls and equivalent temporary measures.',
          'Reassess after layout changes, night shifts, workforce changes, temporary closure of exits or changes to site access; brief workers and subcontractors in languages they understand.',
        ]),
       ],
       checklist: ['Current phase-specific fire risk assessment and site plan','Escape routes, stairs, gates and assembly points clear','Hot-work permits and fire watch arrangements active','Temporary electrical systems inspected','Flammable storage and gas cylinders controlled','Waste removed; fire points and alarms accessible','All shifts and subcontractors briefed and drilled'],
      requiredDocuments: ['Construction fire and emergency plan','Phase-specific fire risk assessments and site layout revisions','Hot-work permits and fire-watch/post-work logs','Temporary electrical inspection records','Flammable storage/SDS and cylinder registers','Fire inspections, drills and corrective-action tracker'],
      interviewQuestions: [FireSafetyQuestion('Why is construction fire risk dynamic?', 'Work areas, fuel loads, temporary systems, escape routes and incomplete permanent protection change throughout project phases.'), FireSafetyQuestion('What must be checked before hot work?', 'Valid permit, area and opposite-side checks, combustible removal/protection, suitable equipment, fire watch, alarm access and approved post-work monitoring.'), FireSafetyQuestion('What if an exit is blocked?', 'Stop affected work, report and restore a safe approved escape route before resuming; implement the emergency plan if people are exposed.')],
      references: ['Applicable UAE labour and fire/life-safety requirements and local authority conditions','Approved project HSE plan, construction fire plan and risk assessments','SDS, hot-work procedure and adopted technical standards'],
    ),
    FireSafetyTopic(
      id: 'FLS-18', title: 'Hot Work Fire Prevention & Fire Watch',
      subtitle: 'Welding, cutting, grinding, spark containment and post-work monitoring',
      icon: Icons.local_fire_department_rounded, accent: Color(0xFFD84315),
      overview: 'Hot work includes welding, cutting, brazing, soldering, grinding and other activities producing flame, heat or sparks. It requires a task-specific risk assessment and permit where mandated by site rules or law. The permit defines area preparation, gas testing where relevant, fire watch, equipment checks, monitoring and hand-back conditions.',
      sections: [
        FireSafetySection('Pre-job planning', ['Prefer cold work or relocation to a designated hot-work area where practicable.', 'Identify combustibles on both sides of walls/floors, concealed voids, ducts, cable trays, drains and lower levels where sparks can travel.', 'Check nearby flammable vapours, process lines, tanks and atmosphere; gas testing and isolation requirements depend on hazard and approved procedure.', 'Confirm suitable extinguisher, alarm/communication, fire watch competency, permit validity and emergency access.']),
        FireSafetySection('Hazards & consequences', ['Sparks and molten metal ignite hidden combustibles or cause delayed smouldering.', 'Flammable vapour or oxygen enrichment can cause flash fire/explosion.', 'Hot slag, cylinders, hoses and electrical leads cause burns, leaks, trips or shock.', 'Fire watch distraction, poor visibility or premature departure allows fire to develop unnoticed.']),
        FireSafetySection('Controls during work', ['Remove combustibles or protect them with suitable non-combustible fire-resistant barriers; protect openings and spark paths.', 'Inspect welding sets, regulators, flashback protection, hoses, cables and cylinders before use; secure cylinders and keep them away from heat.', 'Provide ventilation and task-specific PPE; use screens to protect others without blocking escape or alarm access.', 'Maintain a dedicated fire watch with suitable means of communication and no conflicting duties; watch adjacent/opposite sides as permit requires.', 'Stop work if conditions change, gas test/permit expires, fire protection fails, wind carries sparks or the watch cannot maintain coverage.']),
        FireSafetySection('Close-out & monitoring', ['After work, inspect workface, adjacent spaces, concealed areas and spark travel paths; monitor for the duration stated by the approved permit/risk assessment.', 'Do not use a generic post-work watch duration where site/authority procedure specifies otherwise.', 'Fire watch signs off only after required checks; permit issuer verifies area safe and records close-out.', 'Remove temporary screens and restore fire detection/protection only through authorized process; report any impairment.']),
        FireSafetySection('Emergency response', ['Raise alarm immediately if ignition occurs; stop energy/fuel supply only if safe and trained.', 'Evacuate if fire grows, smoke develops or escape is threatened; call emergency response.', 'Do not re-enter concealed or smoke-affected areas to investigate without authorization and safe conditions.']),
        FireSafetySection('Hot-work permit lifecycle & fire-watch handover', [
          'Before work, inspect both sides of the work surface and adjacent/hidden spaces for combustibles, openings, ducts, cable trays and pathways where sparks or heat can travel.',
          'Remove or protect combustibles using approved non-combustible barriers; protect detectors/sprinklers only through authorized impairment controls, never by informal covering.',
          'Assign a competent fire watch with suitable extinguishing equipment, alarm access, communication and authority to stop work; the watch must not take conflicting duties.',
          'Continue post-work monitoring for the duration set by the approved permit/risk assessment and site procedure; inspect the work area and adjacent spaces before permit close-out.',
        ]),
       ],
       checklist: ['Permit and risk assessment approved and valid','Combustibles/voids/opposite sides assessed and protected','Gas test/isolation completed where required','Equipment and cylinders inspected and secured','Extinguisher, alarm and safe escape available','Dedicated fire watch active and briefed','Post-work checks/monitoring and permit close-out recorded'],
      requiredDocuments: ['Hot-work permit and task risk assessment/JSA','Gas test and isolation certificates where applicable','Fire-watch briefing and monitoring log','Equipment inspection records','Permit close-out and area hand-back','Impairment and restoration records if detection isolated'],
      interviewQuestions: [FireSafetyQuestion('Why inspect the opposite side of a wall?', 'Heat and sparks can pass through openings or conduct through material and ignite hidden combustibles outside the visible work area.'), FireSafetyQuestion('Can the fire watch perform another task?', 'Not if it compromises dedicated observation, response readiness or permit requirements.'), FireSafetyQuestion('When can a hot-work permit be closed?', 'After work stops, required post-work monitoring and area checks are completed, protection is restored and the authorized issuer accepts hand-back.')],
      references: ['Applicable UAE/local requirements and approved site PTW procedure','Project hot-work standard, JSA and fire-watch instructions','SDS and manufacturer guidance for welding/cutting equipment','NFPA 51B where adopted by authority or contract'],
    ),
    FireSafetyTopic(
      id: 'FLS-19', title: 'Fire Safety Inspection, Testing & Maintenance',
      subtitle: 'Assurance, defect classification, records and reliable system readiness',
      icon: Icons.fact_check_rounded, accent: Color(0xFF2E7D32),
      overview: 'Fire protection assurance combines routine visual checks, competent functional tests, preventive maintenance, defect management and formal impairment control. Frequency and acceptance criteria must be taken from current authority requirements, approved design, manufacturer instructions and adopted standards—not copied as universal values.',
      sections: [
        FireSafetySection('Inspection scope', ['Cover alarms, extinguishers, hose reels, hydrants, pumps, sprinklers, suppression, emergency lighting, exit signs, fire doors, dampers and smoke control as installed.', 'Differentiate user visual checks, competent-person inspection, functional testing and specialist performance testing.', 'Verify access, identification, physical condition, normal status, records, overdue actions and management-of-change impacts.', 'Use asset ID and location so every finding can be traced to an exact device/system.']),
        FireSafetySection('Defect risk & prioritization', ['Critical impairment: loss or material reduction of a life-safety function; escalate immediately and apply formal impairment plan.', 'Other defects are risk-ranked using exposure, affected area, redundancy, occupancy, duration and authority criteria.', 'Do not downgrade a defect merely because no incident has occurred.', 'Temporary repair or bypass requires competent approval, documented limits and expiry/review.']),
        FireSafetySection('Work control & quality', ['Use competent, authorized technicians and approved test methods; coordinate with control room, occupants and emergency responders as required.', 'Apply isolation/LOTO where relevant and prevent inadvertent discharge or alarm transmission.', 'After testing, restore every valve, switch, detector, panel, damper and override to approved normal state; independently verify critical restoration.', 'Changes to design, occupancy or use require management of change and authority approval where applicable.']),
        FireSafetySection('Records & performance', ['Maintain asset register, planned maintenance schedule, test sheets, calibration evidence, defects, work orders and closure proof.', 'Trend repeat faults, false alarms, overdue maintenance, impairment hours and recurring causes.', 'Audit contractor competence, parts traceability, test instruments and sign-off quality.', 'Retain records for periods required by law, authority, contract and company document-control procedure.']),
        FireSafetySection('Escalation', ['Notify responsible management immediately for impaired protection, failed test, blocked escape or unclosed critical defect.', 'Implement approved temporary measures, communicate scope and restrictions, and track restoration to verified completion.', 'Do not declare a system serviceable solely from a contractor verbal statement; require documented evidence and functional confirmation.']),
        FireSafetySection('Audit quality, defect closure & assurance', [
          'Build a risk-based asset schedule from the approved fire strategy and asset register; include location, criticality, inspection method, responsible party and due date.',
          'A complete test record identifies asset/tag, location, method, instrument/calibration status, observed result, acceptance criterion, defect, technician and reviewer.',
          'For failed devices or systems, define affected area, life-safety impact, temporary controls, owner, deadline and escalation; verify repair by re-test rather than closing on a work-order note alone.',
          'Review recurring faults, overdue actions, false alarms, impairment duration and contractor performance in management review; feed trends into risk assessment and emergency drills.',
        ]),
       ],
       checklist: ['Current asset register and maintenance schedule','Inspection/test scope and acceptance criteria approved','Technician competency and instruments verified','Defects risk-ranked with owner and due date','Impairments authorized, notified and compensated','Post-work restoration and independent checks recorded','Repeat defects and overdue actions reviewed'],
      requiredDocuments: ['Asset register and maintenance plan','Inspection, functional test and service reports','Technician competency and calibration records','Defect/corrective-action register','Impairment permits and notification log','Restoration and return-to-service certificates'],
      interviewQuestions: [FireSafetyQuestion('What is the difference between inspection and testing?', 'Inspection is condition/visual verification; testing demonstrates function or performance using an approved method. Both may be required.'), FireSafetyQuestion('How should a critical fire-system defect be handled?', 'Escalate immediately, formally declare impairment, assess risk, notify stakeholders, apply approved compensating measures and verify restoration.'), FireSafetyQuestion('What proves maintenance is complete?', 'Traceable service records, test results, defect closure and confirmation that all systems/interfaces are restored to approved normal condition.')],
      references: ['Current UAE Fire and Life Safety Code and authority requirements','Approved O&M manuals, asset register and maintenance contract','Adopted NFPA/EN standards only where applicable and formally adopted','Company document control and impairment procedures'],
    ),
    FireSafetyTopic(
      id: 'FLS-20', title: 'Fire Emergency Response & Incident Management',
      subtitle: 'Alarm, evacuation, accountability, command, recovery and learning',
      icon: Icons.emergency_rounded, accent: Color(0xFFB71C1C),
      overview: 'Fire emergency management protects life through prompt alarm, evacuation, accountability, emergency-service coordination and controlled recovery. Roles, communication, assembly points, assistance for persons needing support and all-clear authority must be established in the site/building emergency plan and practiced through drills.',
      sections: [
        FireSafetySection('Preparedness & roles', ['Define incident controller, fire wardens, first aiders, security/control room, facility representative and external emergency-service interface.', 'Provide clear alarm methods, emergency numbers, site address/access instructions, assembly points and alternate routes.', 'Plan assistance for visitors, contractors, persons with mobility/sensory needs and lone/night-shift workers without exposing helpers to undue risk.', 'Keep current occupancy/headcount information and arrangements for communicating with responders.']),
        FireSafetySection('Immediate actions', ['Discoverer raises alarm, warns nearby people and reports exact location, visible conditions, hazards and any missing persons.', 'Stop work and evacuate by safe designated routes; close doors if safe, do not lock, and never use lifts unless specifically approved for evacuation.', 'Proceed to assembly point, remain available for roll call and report anyone unaccounted for to incident command.', 'Only trained personnel may attempt incipient firefighting when alarm is raised, correct equipment is available and escape remains safe.']),
        FireSafetySection('Incident command & coordination', ['Incident controller establishes command, confirms alarm, directs evacuation/accountability and meets emergency services at agreed access point.', 'Provide responders with building/site plans, hazardous-material information, isolation points, persons missing and fire-system status.', 'Do not silence alarms, re-enter or reset systems until authorized incident command gives direction.', 'Communicate verified information only; avoid rumors and keep access routes clear.']),
        FireSafetySection('After the event', ['Do not reoccupy until competent authority/incident command confirms safe conditions and required approvals are obtained.', 'Preserve evidence, report injury/near miss/property impact, support statutory notifications and conduct investigation under applicable procedure.', 'Inspect fire systems, utilities, structure, smoke contamination and environmental impacts before controlled restart.', 'Capture lessons, assign corrective actions, revise risk assessment/emergency plan and brief affected personnel.']),
        FireSafetySection('Drills & continual improvement', ['Drills test alarm audibility, route usability, warden coverage, roll call, response time, communications and visitor/contractor inclusion.', 'Record scenario, participants, timings, observations, barriers and action owners; avoid treating a drill as successful solely because evacuation occurred.', 'Repeat drills or targeted exercises after major layout/occupancy changes, serious findings or incidents as required by the approved plan.', 'Coordinate drill notification with building management and authorities where required; never create uncontrolled alarm or public panic.']),
        FireSafetySection('Scenario planning, accountability & recovery', [
          'Plan for day/night shifts, contractors, visitors, people requiring assistance, blocked primary routes, power loss, alarm failure and simultaneous incidents; define fallback communications.',
          'Wardens report area status and missing persons to incident command; headcount lists must be current and reconciled without sending anyone back into the building.',
          'At emergency-service handover, provide exact location, fire/smoke conditions, missing-person information, hazardous materials, isolation points and status of fire-protection systems.',
          'Recovery requires authorized all-clear, structural/utility/fire-system checks, controlled re-entry, incident reporting, evidence preservation and tracked corrective actions before normal operations resume.',
        ]),
       ],
       checklist: ['Emergency plan, roles and contact numbers current','Alarm and evacuation routes understood','Assembly point and alternate route identified','Warden/headcount and missing-person reporting process ready','Emergency-service access and site information available','Drills evaluated and actions closed','Re-entry/all-clear authority clearly defined'],
      requiredDocuments: ['Emergency response and evacuation plan','Site/building maps, assembly point and emergency contacts','Warden, first aider and response-team competency records','Drill reports, attendance and corrective-action log','Incident notification, investigation and recovery records','Updated risk assessment and lessons-learned communication'],
      interviewQuestions: [FireSafetyQuestion('What is the first priority during a fire?', 'Protect life: raise alarm, warn people, evacuate safely, account for occupants and summon emergency services.'), FireSafetyQuestion('Who can declare all-clear and allow re-entry?', 'The authorized incident controller/competent authority under the emergency plan, coordinated with emergency services as applicable.'), FireSafetyQuestion('What if a person is missing at assembly?', 'Report name and last known location to incident command immediately; do not re-enter or conduct an untrained search.')],
      references: ['Applicable UAE/local emergency and fire-safety requirements','Approved building/site emergency plan and Civil Defence instructions','Company incident reporting, investigation and business-continuity procedures'],
    ),
  ];
}
